export interface ActionResult {
  success: boolean;
  error?: string;
  /**
   * Lead ID assigned by the Server Action. Present only when a real
   * lead was processed (stored and/or emailed). Honeypot submissions
   * return success WITHOUT a leadId so clients do not fire conversion
   * events or display a reference for a discarded bot submission.
   */
  leadId?: string;
}

export interface LeadNotificationPayload {
  /** Lead ID generated by the Server Action; joins store, email, logs, GA4. */
  leadId: string;
  name: string;
  phone: string;
  serviceType: string;
  email?: string;
  address?: string;
  message?: string;
  sourceUrl: string;
  pageTitle: string;
  timestamp: string;
  formVariant: "compact" | "full";
  userAgent?: string;
}
